from collections import Counter

def transform(g):
 h=len(g); w=len(g[0]); out=[r[:] for r in g]; bad={0,4,6}
 bg=Counter(v for row in g for v in row).most_common(1)[0][0]
 for i in range(h):
  for j in range(w):
   if g[i][j] in bad:
    ns=[g[x][y] for x,y in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=x<h and 0<=y<w and g[x][y] not in bad]
    c=Counter(ns); m=max(c.values()) if c else 0
    winners=[v for v,n in c.items() if n==m]
    out[i][j]=bg if bg in winners else (winners[0] if winners else bg)
 return out
